/* ------------------------------------------------------------------ */
/*  Mini-Game Data Generator Helper                                    */
/* ------------------------------------------------------------------ */

function buildMiniGameForDay(spec: DayTopicSpec): MiniGameConfig {
  const diff = spec.day <= 15 ? 1 : spec.day <= 30 ? 2 : spec.day <= 60 ? 3 : spec.day <= 75 ? 4 : 5;

  if (spec.gameKind === "match") {
    return matchGame(
      spec.gameType,
      spec.gameTitle,
      `Match each concept to its correct architectural role for ${spec.title}.`,
      diff,
      [
        { left: spec.pipelineNodes[0]?.[1] ?? "Component A", right: spec.pipelineNodes[0]?.[2] ?? "Role A" },
        { left: spec.pipelineNodes[1]?.[1] ?? "Component B", right: spec.pipelineNodes[1]?.[2] ?? "Role B" },
        { left: spec.pipelineNodes[2]?.[1] ?? "Component C", right: spec.pipelineNodes[2]?.[2] ?? "Role C" },
        { left: spec.pipelineNodes[3]?.[1] ?? "Component D", right: spec.pipelineNodes[3]?.[2] ?? "Role D" },
      ],
    );
  }

  if (spec.gameKind === "predict") {
    return predictGame(
      spec.gameType,
      spec.gameTitle,
      `// Java Execution Simulation - Day ${spec.day}\npublic class Main {\n  public static void main(String[] args) {\n    System.out.println("${spec.pipelineNodes[0]?.[1]} -> ${spec.pipelineNodes[3]?.[1]}");\n  }\n}`,
      [
        spec.mcqCorrect,
        spec.mcqWrong[0] ?? "Option A",
        spec.mcqWrong[1] ?? "Option B",
        spec.mcqWrong[2] ?? "Option C",
      ],
      0,
      spec.mcqExpl,
      diff,
    );
  }

  if (spec.gameKind === "arrange") {
    return arrangeGame(
      spec.gameType,
      spec.gameTitle,
      `Arrange the processing sequence in correct chronological execution order for: ${spec.title}.`,
      spec.pipelineNodes.map((n, idx) => ({
        id: `block-${idx + 1}`,
        code: `${idx + 1}. ${n[1]} (${n[2]})`,
        order: idx + 1,
      })),
      diff,
    );
  }

  if (spec.gameKind === "error") {
    return errorGame(
      spec.gameType,
      spec.gameTitle,
      `// Bug Hunter Code Inspection - ${spec.title}\n1: @Service\n2: public class OrderProcessor {\n3:   public void execute() {\n4:     // Error condition on Day ${spec.day}\n5:     throw new IllegalStateException("Unresolved logic defect");\n6:   }\n7: }`,
      [
        { line: 5, description: "Unchecked exception thrown without defensive validation checks" },
        { line: 2, description: "Missing constructor dependency injection boundary" },
      ],
      diff,
    );
  }

  if (spec.gameKind === "pipeline") {
    return pipelineGame(
      spec.gameType,
      spec.gameTitle,
      `Construct the correct architecture pipeline stages for ${spec.title}.`,
      spec.pipelineNodes.map((n) => n[1]),
      [0, 1, 2, 3],
      diff,
    );
  }

  // Fallback to fillBlanks
  return fillBlanksGame(
    spec.gameType,
    spec.gameTitle,
    `In Java architecture, the ${spec.pipelineNodes[0]?.[1] ?? "input"} processes through ${spec.pipelineNodes[1]?.[1] ?? "component"} to yield the final ${spec.pipelineNodes[3]?.[1] ?? "result"}.`,
    [
      {
        placeholder: spec.pipelineNodes[0]?.[1] ?? "input",
        answer: spec.pipelineNodes[0]?.[1] ?? "input",
        options: [spec.pipelineNodes[0]?.[1] ?? "input", "GenericHandler", "StaticPool"],
      },
    ],
    diff,
  );
}

/* ------------------------------------------------------------------ */
/*  Assemble All 90 Java Lessons                                       */
/* ------------------------------------------------------------------ */

export function buildJavaCurriculum(): CourseCurriculum {
  const curriculum: CourseCurriculum = {};

  for (const spec of JAVA_DAYS) {
    const isProjectDay = spec.day >= 76;
    const projectConfig = isProjectDay
      ? {
          projectTitle: "Enterprise Distributed E-Commerce Microservices Platform",
          overview: "Architect and build a production-grade, multi-service e-commerce ecosystem incorporating Java 21, Spring Boot 3, Kafka event streaming, Redis caching, Docker containerization, Kubernetes orchestration, and full-stack React.",
          techStack: ["Java 21", "Spring Boot 3", "PostgreSQL", "Apache Kafka", "Redis", "Docker", "Kubernetes", "React", "TypeScript", "Tailwind CSS"],
          milestone: {
            day: spec.day,
            title: spec.title,
            deliverable: `Production Deliverable for Day ${spec.day}: ${spec.description}`,
            acceptanceCriteria: [spec.objectives[0], spec.objectives[1], spec.objectives[2]],
          },
          evaluationRubric: [
            { criteria: "Architecture & Clean Code", weight: 30 },
            { criteria: "Test Coverage & Resilience", weight: 30 },
            { criteria: "Performance & Scalability", weight: 20 },
            { criteria: "Security & Observability", weight: 20 },
          ],
        }
      : undefined;

    curriculum[spec.day] = buildLesson("java", {
      day: spec.day,
      title: spec.title,
      description: spec.description,
      learningObjectives: [spec.objectives[0], spec.objectives[1], spec.objectives[2]],
      animationPipeline: pipeline("java", ...spec.pipelineNodes),
      miniGame: buildMiniGameForDay(spec),
      knowledgeCheck: mcq(
        spec.mcqQuestion,
        spec.mcqCorrect,
        spec.mcqExpl,
        spec.mcqWrong[0] ?? "Option A",
        "Incorrect option.",
        spec.mcqWrong[1] ?? "Option B",
        "Incorrect option.",
        spec.mcqWrong[2] ?? "Option C",
        "Incorrect option.",
      ),
      realWorldExample: realWorld(spec.realScenario, spec.realApp, "Enterprise Financial & Software Services"),
      projectConfig,
    });
  }

  return curriculum;
}

export const JAVA_CURRICULUM = buildJavaCurriculum();
